#include <math.h>
#include <stddef.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include "cfr/checkpoint.h"
#include "cfr/info_node.h"
#include "mus_solver/mus_score.h"
static size_t integrated_hands;
static double random_unit(uint64_t *state) {
    *state += UINT64_C(0x9e3779b97f4a7c15);
    uint64_t z = *state;
    z = (z ^ (z >> 30)) * UINT64_C(0xbf58476d1ce4e5b9);
    z = (z ^ (z >> 27)) * UINT64_C(0x94d049bb133111eb);
    z ^= z >> 31;
    return (double)(z >> 11) * 0x1p-53;
}

static bool valid_evaluation_options(const MusScoreEvaluationOptions *options) {
    return options != NULL && options->min_samples > 0 &&
        options->min_samples <= options->max_samples &&
        isfinite(options->target_standard_error) && options->target_standard_error >= 0 &&
        (options->target_standard_error > 0 ? options->min_samples >= 2
                                            : options->min_samples == options->max_samples);
}

static bool evaluation_target_reached(size_t samples, double variance, double target) {
    return target > 0 && samples >= 2 && sqrt(variance / (double)samples) <= target;
}

Status trial_evaluate(const MusScoreGame *game, const InfoStore *store,
    const MusScoreEvaluationOptions *options, uint64_t seed, MusScoreEvaluation *result) {
    if (game == NULL || store == NULL || result == NULL || !valid_evaluation_options(options))
        return CFR_STATUS_INVALID_ARGUMENT;
    MusGameState *state = malloc(sizeof(*state));
    if (state == NULL)
        return CFR_STATUS_OUT_OF_MEMORY;
    const GameOperations *ops = game->game.trusted_operations;
    const void *context = game->game.context;
    double mean = 0, m2 = 0;
    MusScoreEvaluation evaluation = {0};
    Status status = mus_score_game_state_init(state, game);
    if (status != CFR_STATUS_SUCCESS) {
        free(state);
        return status;
    }
    /* Only the active state needs resetting. Each action writes its undo
     * entry before that entry can be read. */
    unsigned char root[offsetof(MusGameState, undo_history)];
    memcpy(root, state, sizeof(root));
    for (size_t sample = 0; sample < options->max_samples; sample += 1) {
        bool integrated = false;
        double integrated_value = 0;
        memcpy(state, root, sizeof(root));
        state->undo_count = 0;
        GameState *raw = mus_game_state_as_game_state(state);
        while (state->model.phase != MUS_PHASE_TERMINAL) {
            Action actions[MUS_GAME_MAX_LEGAL_ACTIONS];
            Probability probabilities[MUS_GAME_MAX_LEGAL_ACTIONS];
            size_t count = 0;
            Actor actor;
            status = ops->current_actor(context, raw, &actor);
            if (status != CFR_STATUS_SUCCESS)
                break;
            if (actor.kind == CFR_ACTOR_CHANCE) {
                status = ops->chance_outcomes(context, raw, actions, probabilities,
                                              MUS_GAME_MAX_LEGAL_ACTIONS, &count);
            } else {
                InfoSetKey key;
                const InfoNode *node;
                status = ops->legal_actions(context, raw, actions,
                                            MUS_GAME_MAX_LEGAL_ACTIONS, &count);
                if (status != CFR_STATUS_SUCCESS)
                    break;
                status = ops->information_set_key(context, raw, &key);
                if (status != CFR_STATUS_SUCCESS)
                    break;
                status = cfr_info_store_find_const(store, key, &node);
                if (status == CFR_STATUS_NOT_FOUND) {
                    for (size_t i = 0; i < count; i += 1)
                        probabilities[i] = 1.0 / (double)count;
                    status = CFR_STATUS_SUCCESS;
                } else if (status == CFR_STATUS_SUCCESS) {
                    status = node->action_count == count
                                 ? cfr_info_node_average_strategy(node, probabilities, count)
                                 : CFR_STATUS_INVALID_ARGUMENT;
                }
            }
            if (status != CFR_STATUS_SUCCESS)
                break;
            if (actor.kind != CFR_ACTOR_CHANCE && count <= 2 &&
                (state->model.phase == MUS_PHASE_JUEGO || state->model.phase == MUS_PHASE_PUNTO)) {
                bool all_terminal = true;
                double expected = 0;
                for (size_t i = 0; i < count; ++i) {
                    status = ops->apply_action(context, raw, actions[i]);
                    if (status != CFR_STATUS_SUCCESS) break;
                    all_terminal = state->model.phase == MUS_PHASE_TERMINAL;
                    Utility child_value = 0;
                    if (all_terminal) status = mus_score_terminal_utility(state, CFR_PLAYER_0, &child_value);
                    const Status undone = ops->undo_action(context, raw);
                    if (undone != CFR_STATUS_SUCCESS) status = undone;
                    if (status != CFR_STATUS_SUCCESS || !all_terminal) break;
                    expected += probabilities[i] * child_value;
                }
                if (status != CFR_STATUS_SUCCESS) break;
                if (all_terminal) {
                    integrated = true;
                    integrated_value = expected;
                    integrated_hands++;
                    break;
                }
            }
            double draw = random_unit(&seed);
            size_t selected = 0;
            while (selected + 1 < count && draw >= probabilities[selected]) {
                draw -= probabilities[selected];
                selected += 1;
            }
            status = ops->apply_action(context, raw, actions[selected]);
            if (status != CFR_STATUS_SUCCESS)
                break;
        }
        if (status != CFR_STATUS_SUCCESS)
            break;
        Utility utility;
        if (integrated) utility = integrated_value;
        else status = mus_score_terminal_utility(state, CFR_PLAYER_0, &utility);
        if (status != CFR_STATUS_SUCCESS)
            break;
        const double delta = utility - mean;
        mean += delta / (double)(sample + 1);
        m2 += delta * (utility - mean);
        evaluation.samples = sample + 1;
        if (options->target_standard_error > 0 && evaluation.samples >= options->min_samples &&
            evaluation_target_reached(evaluation.samples, m2 / (double)sample,
                                      options->target_standard_error)) {
            evaluation.target_reached = true;
            break;
        }
    }
    free(state);
    if (status == CFR_STATUS_SUCCESS) {
        evaluation.value = mean;
        evaluation.variance_known = evaluation.samples >= 2;
        if (evaluation.variance_known) {
            evaluation.sample_variance = m2 / (double)(evaluation.samples - 1);
            evaluation.standard_error = sqrt(evaluation.sample_variance / (double)evaluation.samples);
        }
        *result = evaluation;
    }
    return status;
}

int main(int argc, char **argv) {
    if (argc != 7) return 2;
    const bool integrate = strcmp(argv[1], "integrate") == 0;
    const unsigned int a = (unsigned int)strtoul(argv[3], NULL, 10);
    const unsigned int b = (unsigned int)strtoul(argv[4], NULL, 10);
    const size_t samples = strtoull(argv[5], NULL, 10), repeats = strtoull(argv[6], NULL, 10);
    char path[4096];
    (void)snprintf(path, sizeof(path), "%s/values.txt", argv[2]);
    FILE *stream = fopen(path, "r");
    MusScoreTable table;
    if (!stream || mus_score_table_read(stream, &table) != CFR_STATUS_SUCCESS || fclose(stream) != 0) return 3;
    MusScoreGame game;
    MusGameState *state = malloc(sizeof(*state));
    InfoStore store = {0};
    Trainer trainer;
    if (!state || mus_score_game_init(&game, &table, a, b) != CFR_STATUS_SUCCESS ||
        mus_score_game_state_init(state, &game) != CFR_STATUS_SUCCESS) return 4;
    (void)snprintf(path, sizeof(path), "%s/score-%02u-%02u.cfr.zst", argv[2], a, b);
    stream = fopen(path, "rb");
    if (!stream || cfr_checkpoint_read_zstd(stream, &game.game, mus_game_state_as_game_state(state),
        &store, &trainer) != CFR_STATUS_SUCCESS || fclose(stream) != 0) return 5;
    MusScoreEvaluationOptions options = {.min_samples = samples, .max_samples = samples};
    struct timespec before, after;
    if (clock_gettime(CLOCK_MONOTONIC, &before) != 0) return 6;
    double mean = 0, variance = 0, between_m2 = 0;
    for (size_t i = 0; i < repeats; ++i) {
        MusScoreEvaluation evaluation;
        const Status status = integrate ? trial_evaluate(&game, &store, &options, i, &evaluation)
            : mus_score_evaluate_with_options(&game, &store, &options, i, &evaluation);
        if (status != CFR_STATUS_SUCCESS) return 7;
        const double delta = evaluation.value - mean;
        mean += delta / (double)(i + 1);
        between_m2 += delta * (evaluation.value - mean);
        variance += evaluation.sample_variance / (double)repeats;
    }
    if (clock_gettime(CLOCK_MONOTONIC, &after) != 0) return 8;
    const double elapsed = (double)(after.tv_sec-before.tv_sec) + (double)(after.tv_nsec-before.tv_nsec)/1e9;
    printf("mode=%s seconds=%.17g mean=%.17g mean_sample_variance=%.17g seed_mean_variance=%.17g integrated_hands=%zu samples=%zu repeats=%zu\n",
        argv[1], elapsed, mean, variance, between_m2/(double)(repeats-1), integrated_hands, samples, repeats);
    (void)cfr_info_store_destroy(&store);
    free(state);
    return 0;
}

